import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import MarkdownIt from "markdown-it";
import hljs from "highlight.js";

export interface Frontmatter {
  title: string;
  date: Date;
  tags: string[];
  draft: boolean;
  layout: string;
  [key: string]: unknown;
}

export interface Post extends Frontmatter {
  /** Slug derived from the file path relative to the source dir, e.g. "posts/hello". */
  slug: string;
  /** Site-relative URL, e.g. "/posts/hello/". */
  url: string;
  /** Rendered HTML body. */
  html: string;
  /** Raw markdown body. */
  raw: string;
}

export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export const md: MarkdownIt = new MarkdownIt({
  html: true,
  linkify: true,
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      const { value } = hljs.highlight(code, { language: lang, ignoreIllegals: true });
      return `<pre><code class="hljs language-${lang}">${value}</code></pre>`;
    }
    return `<pre><code class="hljs">${escapeHtml(code)}</code></pre>`;
  },
});

/** Normalize raw frontmatter data into a well-typed Frontmatter object. */
export function normalizeFrontmatter(data: Record<string, unknown>, fallbackTitle: string): Frontmatter {
  const title = typeof data.title === "string" && data.title.trim() !== "" ? data.title : fallbackTitle;

  let date: Date;
  if (data.date instanceof Date) date = data.date;
  else if (typeof data.date === "string" || typeof data.date === "number") {
    const parsed = new Date(data.date);
    date = Number.isNaN(parsed.getTime()) ? new Date(0) : parsed;
  } else date = new Date(0);

  let tags: string[];
  if (Array.isArray(data.tags)) tags = data.tags.map(String).filter((t) => t.trim() !== "");
  else if (typeof data.tags === "string") tags = data.tags.split(",").map((t) => t.trim()).filter(Boolean);
  else tags = [];

  const draft = data.draft === true;
  const layout = typeof data.layout === "string" && data.layout.trim() !== "" ? data.layout : "post";

  return { ...data, title, date, tags, draft, layout };
}

export function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9/]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-{2,}/g, "-");
}

/** Parse a single markdown document (frontmatter + body) into a Post. */
export function parsePost(rawFile: string, relPath: string): Post {
  const { data, content } = matter(rawFile);
  const noExt = relPath.replace(/\\/g, "/").replace(/\.(md|markdown)$/i, "");
  const slug = noExt.split("/").map(slugify).join("/");
  const fallbackTitle = path.basename(noExt);
  const fm = normalizeFrontmatter(data, fallbackTitle);
  return {
    ...fm,
    slug,
    url: `/${slug}/`,
    html: md.render(content),
    raw: content,
  };
}

async function walk(dir: string, base: string): Promise<string[]> {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  const out: string[] = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(full, base)));
    else out.push(path.relative(base, full));
  }
  return out;
}

export interface LoadResult {
  posts: Post[];
  /** Relative paths of non-markdown files to copy through verbatim. */
  assets: string[];
}

/** Load all markdown files under sourceDir. Posts are sorted newest first. */
export async function loadContent(sourceDir: string, includeDrafts = false): Promise<LoadResult> {
  const files = await walk(sourceDir, sourceDir);
  const posts: Post[] = [];
  const assets: string[] = [];
  for (const rel of files) {
    if (/\.(md|markdown)$/i.test(rel)) {
      const raw = await fs.readFile(path.join(sourceDir, rel), "utf8");
      const post = parsePost(raw, rel);
      if (post.draft && !includeDrafts) continue;
      posts.push(post);
    } else {
      assets.push(rel);
    }
  }
  posts.sort((a, b) => b.date.getTime() - a.date.getTime());
  return { posts, assets };
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";

/**
 * Template directory convention:
 *   templates/
 *     layouts/    -> layouts (default.hbs, post.hbs, ...); receive {{{content}}}
 *     partials/   -> registered as partials by filename (header.hbs -> {{> header}})
 *     index.hbs   -> site index page
 *     tag.hbs     -> per-tag index page (optional; falls back to index.hbs)
 */
export class TemplateEngine {
  private hb = Handlebars.create();
  private layouts = new Map<string, Handlebars.TemplateDelegate>();
  private pages = new Map<string, Handlebars.TemplateDelegate>();

  private constructor() {
    this.hb.registerHelper("formatDate", (date: unknown, fmt?: unknown) => {
      const d = date instanceof Date ? date : new Date(String(date));
      if (Number.isNaN(d.getTime())) return "";
      if (fmt === "iso") return d.toISOString();
      return d.toISOString().slice(0, 10);
    });
    this.hb.registerHelper("eq", (a: unknown, b: unknown) => a === b);
  }

  static async load(templateDir: string): Promise<TemplateEngine> {
    const engine = new TemplateEngine();

    const readDirSafe = async (dir: string) => {
      try {
        return (await fs.readdir(dir)).filter((f) => f.endsWith(".hbs"));
      } catch {
        return [];
      }
    };

    const partialsDir = path.join(templateDir, "partials");
    for (const file of await readDirSafe(partialsDir)) {
      const name = path.basename(file, ".hbs");
      engine.hb.registerPartial(name, await fs.readFile(path.join(partialsDir, file), "utf8"));
    }

    const layoutsDir = path.join(templateDir, "layouts");
    for (const file of await readDirSafe(layoutsDir)) {
      const name = path.basename(file, ".hbs");
      engine.layouts.set(name, engine.hb.compile(await fs.readFile(path.join(layoutsDir, file), "utf8")));
    }

    for (const file of await readDirSafe(templateDir)) {
      const name = path.basename(file, ".hbs");
      engine.pages.set(name, engine.hb.compile(await fs.readFile(path.join(templateDir, file), "utf8")));
    }

    return engine;
  }

  hasLayout(name: string): boolean {
    return this.layouts.has(name);
  }

  hasPage(name: string): boolean {
    return this.pages.has(name);
  }

  /** Render a layout by name; `content` is available as {{{content}}}. Falls back to "default". */
  renderLayout(name: string, context: Record<string, unknown>): string {
    const layout = this.layouts.get(name) ?? this.layouts.get("default");
    if (!layout) throw new Error(`No layout "${name}" and no "default" layout found`);
    return layout(context);
  }

  /** Render a top-level page template (index.hbs, tag.hbs). */
  renderPage(name: string, context: Record<string, unknown>): string {
    const page = this.pages.get(name);
    if (!page) throw new Error(`No page template "${name}.hbs" found in template directory`);
    return page(context);
  }
}

import type { Post } from "./content.js";
import { escapeHtml } from "./content.js";

export interface RssOptions {
  title: string;
  description: string;
  baseUrl: string;
  limit?: number;
}

/** Generate an RSS 2.0 feed for the given posts (assumed sorted newest first). */
export function generateRss(posts: Post[], opts: RssOptions): string {
  const base = opts.baseUrl.replace(/\/$/, "");
  const items = posts.slice(0, opts.limit ?? 20).map((p) => {
    const link = `${base}${p.url}`;
    return [
      "    <item>",
      `      <title>${escapeHtml(p.title)}</title>`,
      `      <link>${escapeHtml(link)}</link>`,
      `      <guid isPermaLink="true">${escapeHtml(link)}</guid>`,
      `      <pubDate>${p.date.toUTCString()}</pubDate>`,
      ...p.tags.map((t) => `      <category>${escapeHtml(t)}</category>`),
      `      <description><![CDATA[${p.html.replace(/\]\]>/g, "]]]]><![CDATA[>")}]]></description>`,
      "    </item>",
    ].join("\n");
  });

  return [
    `<?xml version="1.0" encoding="UTF-8"?>`,
    `<rss version="2.0">`,
    `  <channel>`,
    `    <title>${escapeHtml(opts.title)}</title>`,
    `    <link>${escapeHtml(base + "/")}</link>`,
    `    <description>${escapeHtml(opts.description)}</description>`,
    `    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>`,
    ...items,
    `  </channel>`,
    `</rss>`,
    ``,
  ].join("\n");
}

import fs from "node:fs/promises";
import path from "node:path";
import { loadContent, slugify, type Post } from "./content.js";
import { TemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";

export interface BuildOptions {
  sourceDir: string;
  templateDir: string;
  outDir: string;
  baseUrl?: string;
  siteTitle?: string;
  siteDescription?: string;
  includeDrafts?: boolean;
  clean?: boolean;
}

export interface BuildResult {
  posts: Post[];
  tags: Map<string, Post[]>;
  /** Output-dir-relative paths of every file written. */
  files: string[];
}

async function writeFile(outDir: string, rel: string, content: string, files: string[]): Promise<void> {
  const full = path.join(outDir, rel);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, content, "utf8");
  files.push(rel);
}

export function collectTags(posts: Post[]): Map<string, Post[]> {
  const tags = new Map<string, Post[]>();
  for (const post of posts) {
    for (const tag of post.tags) {
      const key = slugify(tag);
      const list = tags.get(key);
      if (list) list.push(post);
      else tags.set(key, [post]);
    }
  }
  return tags;
}

export async function buildSite(opts: BuildOptions): Promise<BuildResult> {
  const {
    sourceDir,
    templateDir,
    outDir,
    baseUrl = "http://localhost:3000",
    siteTitle = "My Site",
    siteDescription = "",
    includeDrafts = false,
    clean = true,
  } = opts;

  if (clean) await fs.rm(outDir, { recursive: true, force: true });
  await fs.mkdir(outDir, { recursive: true });

  const engine = await TemplateEngine.load(templateDir);
  const { posts, assets } = await loadContent(sourceDir, includeDrafts);
  const tags = collectTags(posts);
  const files: string[] = [];

  const site = { title: siteTitle, description: siteDescription, baseUrl, tags: [...tags.keys()].sort() };

  // Post pages: <slug>/index.html
  for (const post of posts) {
    const html = engine.renderLayout(post.layout, { ...post, content: post.html, site, posts });
    await writeFile(outDir, path.join(post.slug, "index.html"), html, files);
  }

  // Site index
  const indexHtml = engine.renderPage("index", { site, posts });
  await writeFile(outDir, "index.html", indexHtml, files);

  // Tag index pages: tags/<tag>/index.html
  const tagPage = engine.hasPage("tag") ? "tag" : "index";
  for (const [tag, tagPosts] of tags) {
    const html = engine.renderPage(tagPage, { site, posts: tagPosts, tag });
    await writeFile(outDir, path.join("tags", tag, "index.html"), html, files);
  }

  // RSS feed
  const rss = generateRss(posts, { title: siteTitle, description: siteDescription, baseUrl });
  await writeFile(outDir, "feed.xml", rss, files);

  // Pass-through assets from the source dir
  for (const rel of assets) {
    const dest = path.join(outDir, rel);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.copyFile(path.join(sourceDir, rel), dest);
    files.push(rel);
  }

  return { posts, tags, files };
}

import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { buildSite, type BuildOptions } from "./build.js";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff2": "font/woff2",
};

export const RELOAD_SCRIPT = `<script>
(() => {
  const ws = new WebSocket("ws://" + location.host + "/__livereload");
  ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
  ws.onclose = () => setTimeout(() => location.reload(), 1000);
})();
</script>`;

/** Inject the live-reload script before </body>, or append if no body tag. */
export function injectReloadScript(html: string): string {
  const idx = html.lastIndexOf("</body>");
  if (idx === -1) return html + RELOAD_SCRIPT;
  return html.slice(0, idx) + RELOAD_SCRIPT + html.slice(idx);
}

export interface DevServer {
  server: http.Server;
  port: number;
  close(): Promise<void>;
}

/** Resolve a URL path to a file inside root, guarding against path traversal. */
export async function resolveFile(root: string, urlPath: string): Promise<string | null> {
  const decoded = decodeURIComponent(urlPath.split("?")[0] ?? "/");
  const safe = path.normalize(decoded).replace(/^(\.\.[/\\])+/, "");
  let full = path.join(root, safe);
  if (!full.startsWith(path.resolve(root))) return null;
  try {
    const stat = await fs.stat(full);
    if (stat.isDirectory()) full = path.join(full, "index.html");
    await fs.access(full);
    return full;
  } catch {
    return null;
  }
}

export async function startDevServer(opts: BuildOptions & { port?: number }): Promise<DevServer> {
  const port = opts.port ?? 3000;
  await buildSite(opts);

  const server = http.createServer(async (req, res) => {
    const file = await resolveFile(opts.outDir, req.url ?? "/");
    if (!file) {
      res.writeHead(404, { "content-type": "text/plain" });
      res.end("Not found");
      return;
    }
    const ext = path.extname(file).toLowerCase();
    const mime = MIME[ext] ?? "application/octet-stream";
    let body: Buffer | string = await fs.readFile(file);
    if (ext === ".html") body = injectReloadScript(body.toString("utf8"));
    res.writeHead(200, { "content-type": mime });
    res.end(body);
  });

  const wss = new WebSocketServer({ server, path: "/__livereload" });
  const broadcast = (msg: string) => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  let timer: NodeJS.Timeout | undefined;
  const watcher = chokidar.watch([opts.sourceDir, opts.templateDir], {
    ignoreInitial: true,
  });
  watcher.on("all", () => {
    // Debounce bursts of file events into a single rebuild.
    clearTimeout(timer);
    timer = setTimeout(async () => {
      try {
        await buildSite(opts);
        broadcast("reload");
        console.log("[ssg] rebuilt, reload sent");
      } catch (err) {
        console.error("[ssg] rebuild failed:", err);
      }
    }, 100);
  });

  await new Promise<void>((resolve) => server.listen(port, resolve));
  const actualPort = (server.address() as { port: number }).port;
  console.log(`[ssg] dev server at http://localhost:${actualPort}/`);

  return {
    server,
    port: actualPort,
    async close() {
      clearTimeout(timer);
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve())),
      );
    },
  };
}

#!/usr/bin/env node
import { pathToFileURL } from "node:url";
import { Command } from "commander";
import { buildSite, type BuildOptions } from "./build.js";
import { startDevServer, type DevServer } from "./server.js";

interface CommonFlags {
  source: string;
  templates: string;
  out: string;
  baseUrl: string;
  title: string;
  description: string;
  drafts: boolean;
}

function toBuildOptions(flags: CommonFlags): BuildOptions {
  return {
    sourceDir: flags.source,
    templateDir: flags.templates,
    outDir: flags.out,
    baseUrl: flags.baseUrl,
    siteTitle: flags.title,
    siteDescription: flags.description,
    includeDrafts: flags.drafts,
  };
}

function addCommonFlags(cmd: Command): Command {
  return cmd
    .option("-s, --source <dir>", "source directory of markdown files", "content")
    .option("-t, --templates <dir>", "template directory", "templates")
    .option("-o, --out <dir>", "output directory", "dist")
    .option("--base-url <url>", "site base URL (used in RSS)", "http://localhost:3000")
    .option("--title <title>", "site title", "My Site")
    .option("--description <text>", "site description", "")
    .option("--drafts", "include draft posts", false);
}

export interface CliHooks {
  /** Called with the started dev server so tests/callers can shut it down. */
  onServe?: (server: DevServer) => void;
}

export function makeProgram(hooks: CliHooks = {}): Command {
  const program = new Command();
  program.name("ssg").description("Static site generator").version("1.0.0");

  addCommonFlags(program.command("build"))
    .description("build the site once")
    .action(async (flags: CommonFlags) => {
      const result = await buildSite(toBuildOptions(flags));
      console.log(`[ssg] built ${result.posts.length} posts, ${result.files.length} files -> ${flags.out}`);
    });

  addCommonFlags(program.command("serve"))
    .description("build, serve, and rebuild on change with live reload")
    .option("-p, --port <port>", "port to listen on", (v) => Number.parseInt(v, 10), 3000)
    .action(async (flags: CommonFlags & { port: number }) => {
      const server = await startDevServer({ ...toBuildOptions(flags), port: flags.port });
      hooks.onServe?.(server);
    });

  return program;
}

export async function runCli(argv: string[], hooks: CliHooks = {}): Promise<void> {
  await makeProgram(hooks).parseAsync(argv);
}

const isMain =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  runCli(process.argv).catch((err) => {
    console.error(err instanceof Error ? err.message : err);
    process.exit(1);
  });
}
